export const SKY_NOTE='한국 시간에 맞춰 분위기가 바뀌어요. 달과 별자리는 게임용 연출이며, 실제 하늘이나 달의 위상을 나타내지 않아요.';
export const SKY_MOODS=Object.freeze({morning:{id:'morning',label:'아침',skyTop:'#b5d3e5',horizon:'#f1dfc2',water:'#c3dfe1',sun:'#fff1cf',ambient:2.35,sunIntensity:3.5,fill:1.15,glow:0},day:{id:'day',label:'낮',skyTop:'#a7cce7',horizon:'#e6eff0',water:'#c4e2e6',sun:'#fff0d4',ambient:2.6,sunIntensity:4.3,fill:1.2,glow:0},evening:{id:'evening',label:'저녁',skyTop:'#aca9cf',horizon:'#edc29f',water:'#b8ccd6',sun:'#ffd5af',ambient:2.1,sunIntensity:2.8,fill:1.05,glow:.45},night:{id:'night',label:'밤',skyTop:'#263754',horizon:'#647c9d',water:'#819daf',sun:'#d7e6ff',ambient:1.65,sunIntensity:1.7,fill:1.15,glow:1}});
const clockFormat=new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Seoul',hour:'2-digit',minute:'2-digit',hourCycle:'h23'});
export function timeOfDay(date=new Date()){const clock=clockFormat.format(date),hour=Number(clock.split(':')[0]),id=hour>=6&&hour<11?'morning':hour>=11&&hour<17?'day':hour>=17&&hour<20?'evening':'night';return {...SKY_MOODS[id],clock,timeZone:'Asia/Seoul'};}
// Decorative schematic patterns; uniformly scaled, never presented as the current local sky.
// References: NASA stargaze/Spolaris.htm and science.nasa.gov/asset/hubble/orion-constellation/.
export const CONSTELLATIONS={dipper:{label:'북두칠성',stars:[['Dubhe',100,0],['Merak',101,23],['Phecda',69,35],['Megrez',56,20],['Alioth',33,25],['Mizar',15,29],['Alkaid',0,54]].map(([name,x,y])=>({name,x,y})),edges:[[0,1],[1,2],[2,3],[3,0],[3,4],[4,5],[5,6]]},orion:{label:'오리온자리',stars:[['Betelgeuse',8,6],['Bellatrix',46,12],['Alnitak',26,53],['Alnilam',32,49],['Mintaka',38,45],['Saiph',18,91],['Rigel',58,83]].map(([name,x,y])=>({name,x,y})),edges:[[0,1],[1,4],[4,6],[6,5],[5,2],[2,0],[2,3],[3,4]]}};
